def encode(message):
    def swap_case(c):
        if c.islower():
            return c.upper()
        elif c.isupper():
            return c.lower()
        else:
            return c

    def replace_vowel(c):
        vowels = 'aeiou'
        if c.lower() in vowels:
            # Find the position of the vowel
            index = vowels.index(c.lower())
            # Calculate the new vowel by adding 2 positions
            new_vowel = vowels[(index + 2) % len(vowels)]
            # Swap the case of the new vowel
            return swap_case(new_vowel)
        else:
            return c

    # Apply the transformations to each character in the message
    encoded_message = ''.join([replace_vowel(c) for c in message])
    return encoded_message

