```python
def count_even_odd_palindromes(n):
    def is_palindrome(num):
        # Convert the number to a string to check for palindrome property
        return str(num) == str(num)[::-1]

    even_count = 0
    odd_count = 0

    # Check for palindromes with 1 digit
    for i in range(1, 10):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    # Check for palindromes with 2 digits
    for i in range(10, 100):
        num = i // 10 + i % 10 * 10
        if is_palindrome(num):
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    # Check for palindromes with 3 digits
    for i in range(100, 1000):
        for j in range(10):
            num = i // 100 + (i // 10) % 10 * 10 + j * 100
            if is_palindrome(num):
                if num % 2 == 0:
                    even_count += 1
                else:
                    odd_count += 1

    return (even_count, odd_count)

