def even_odd_palindrome(n):
    """Time O(N^2) | Space O(N^2)"""
    # odd palindrome
    def is_odd_palindrome(m):
        str_m = str(m)
        mid = len(str_m) // 2
        return str_m[:mid] == str_m[:mid + 1][::-1]

    # even palindrome
    def is_even_palindrome(m):
        str_m = str(m)
        mid = len(str_m) // 2
        return str_m[:mid] == str_m[:mid][::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_odd_palindrome(i):
            odd_count += 1
        elif is_even_palindrome(i):
            even_count += 1

    return (even_count, odd_count)
