class Solution:
    def evenOddPalindromePairs(self, head: ListNode) -> List[int]:
        if not head:
            return (0, 0)

        # Function to determine if a string is a palindrome
        def is_palindrome(s):
            return s == s[::-1]

        # Initialize counters for even and odd palindromes
        even_count, odd_count = 0, 0

        # Convert linked list to a list of digits
        current = head
        digit_list = []
        while current:
            digit_list.append(current.val)
            current = current.next

        # Check for even palindromes
        for i in range(len(digit_list)):
            for j in range(i, len(digit_list)):
                if is_palindrome(str(digit_list[i:j+1])):
                    even_count += 1

        # Check for odd palindromes
        for i in range(len(digit_list)):
            for j in range(i+1, len(digit_list)):
                if is_palindrome(str(digit_list[i:j+1])):
                    odd_count += 1

        return (even_count, odd_count)

